type Task={id:string,title:string,status:Status,priority:'Highest'|'High'|'Medium'|'Low',assignee:string,initials:string,points:number,labels:string[],doc:DocStatus,description:string,epic:string,project?:string,sprintId?:string|number,startDate?:string,assignedDate?:string,dueDate?:string,issueType?:string,type?:'task'|'milestone',submission?:WorkSubmission,dependencies?:Dependency[]};
