function Notifications({close}:{close:()=>void}){const [items,setItems]=useState<{id:string,message:string,createdAt:string}[]>([]),[error,setError]=useState(''),[loading,setLoading]=useState(true);useEffect(()=>{api<typeof items>('/notifications').then(setItems).catch(()=>setError('Could not load notifications.')).finally(()=>setLoading(false))},[]);return <div className="notifications" onClick={e=>e.stopPropagation()}><div className="panel-head"><b>Notifications</b><button aria-label="Close notifications" onClick={close}><X size={16}/></button></div>{loading?<p>Loading…</p>:error?<p role="alert">{error}</p>:items.length?items.map(item=><div className="notification" key={item.id}><Bell size={16}/><span><b>{item.message}</b><small>{new Date(item.createdAt).toLocaleString()}</small></span></div>):<p>No notifications yet.</p>}</div>}
function IssueDrawer({task,tasks,close,submit,change,workMode,openDoc}:{task:Task,tasks:Task[],close:()=>void,submit:()=>void,change:(x:Partial<Task>)=>void,workMode?:boolean,openDoc?:()=>void}){const dependencies=task.dependencies||[];const canSubmit=task.status!=='Done';return <><div className="scrim" onClick={close}/><aside className="drawer" aria-label={`Task ${task.id}`}><div className="drawer-head"><span className="issue-key"><CircleDot size={16}/>{task.id}</span><div><button className="icon-btn" aria-label="More task actions"><MoreHorizontal size={18}/></button><button className="icon-btn" onClick={close} aria-label="Close task"><X size={19}/></button></div></div><div className="drawer-title"><h1>{task.title}</h1><div><button className="status-button" onClick={()=>change({status:task.status==='Done'?'To Do':'Done'})}><CheckCircle2 size={15}/>{task.status}<ChevronDown size={13}/></button><button className="secondary">{task.priority}<ChevronDown size={13}/></button></div></div><div className="drawer-body"><div className="issue-main"><h4>Description</h4><p>{task.description} The implementation should be production-ready, covered by tests, and follow existing platform conventions.</p><h4>Requirements</h4><ul><li>Implement the agreed technical solution.</li><li>Cover important error and edge cases.</li><li>Provide evidence and a clear work summary.</li></ul><section className="dependency-summary"><div className="dependency-heading"><Layers size={16}/><div><h4>Dependencies</h4><small>{dependencies.length?'This task has linked work.':'This task has no dependencies.'}</small></div></div>{dependencies.length?<div className="dependency-list">{dependencies.map(dependency=>{const linked=tasks.find(item=>item.id===dependency.issueId);const label=dependency.type==='blockedBy'?'Blocked by':dependency.type==='blocks'?'Blocks':'Related to';return <div className={'dependency-item '+dependency.type} key={dependency.type+dependency.issueId}><span>{label}</span><b>{dependency.issueId} · {linked?.title||'Linked task'}</b><Badge kind={linked?.status==='Done'?'doc-state approved':'doc-state needs-review'}>{linked?.status||'Unknown status'}</Badge></div>})}</div>:<p className="dependency-clear"><CheckCircle2 size={15}/> No other task must be completed before this one.</p>}</section>{task.submission&&<section className="employee-work"><div className="work-heading"><span><Upload size={15}/></span><div><h4>Employee submitted work</h4><small>{task.submission.submittedAt?'Submitted '+new Date(task.submission.submittedAt).toLocaleString():'Submitted work'}</small></div></div><h5>What was completed</h5><p>{task.submission.summary}</p><h5>Evidence</h5><div className="submitted-evidence">{task.submission.evidence.length?task.submission.evidence.map(item=><span key={item}><Paperclip size={13}/>{item}</span>):<small>No evidence attached.</small>}</div>{task.submission.repository&&<div className="submission-git"><b>Git</b><span>{task.submission.repository}</span><span>{task.submission.branch}</span><span>{task.submission.pullRequest}</span></div>}</section>}<h4>Attachments <button className="link-btn"><Paperclip size={14}/> Add</button></h4><div className="attachments"><span><FileText/>implementation-notes.md<small>12 KB</small></span><span><FileText/>auth-flow.png<small>248 KB</small></span></div><h4>Comments <button className="link-btn">Add comment</button></h4><div className="comment"><Avatar name="Sara" initials="SA"/><p><b>Sara Khalil</b><small>Yesterday</small>Looks good. Please include the edge cases around expired sessions.</p></div><div className="comment"><Avatar name="Ahmed" initials="AH"/><p><b>Ahmed Hassan</b><small>2 days ago</small>I’ve added the acceptance criteria and linked the epic.</p></div></div><aside className="issue-details"><h4>Details</h4>{[['Assignee',task.assignee],['Reporter','Ahmed Hassan'],['Sprint','Sprint 12'],['Epic',task.epic],['Story points',String(task.points)],['Due date','Oct 18, 2026'],['Documentation',task.doc]].map(([x,y])=><div key={x}><span>{x}</span><b>{y}</b></div>)}<h4>Labels</h4><div className="labels">{task.labels.map(x=><Badge key={x}>{x}</Badge>)}</div><h4>Activity</h4><div className="history"><p>Ahmed moved this to <b>{task.status}</b></p><small>Today, 9:42 AM</small><p>Task created</p><small>Oct 7, 2026</small></div></aside></div><footer>{canSubmit&&<button className="create" onClick={submit}><Upload size={16}/> Submit work</button>}{task.doc!=='Not Started'&&openDoc&&<button className="secondary" onClick={openDoc}>{workMode?'View documentation':'Open documentation'}</button>}<button className="secondary" onClick={close}>Close</button></footer></aside></>}
function Submission({task,close,generate}:{task:Task,close:()=>void,generate:(t:Task,work:WorkSubmission)=>void}){const [busy,setBusy]=useState(false),[evidence,setEvidence]=useState<string[]>([]),[summary,setSummary]=useState('Describe the work you completed, the result, and any decisions or findings.'),[aiPrompt,setAiPrompt]=useState(''),[documentStructure,setDocumentStructure]=useState('Technical implementation guide'),[customSections,setCustomSections]=useState(''),[useGit,setUseGit]=useState(false);const [repository,setRepository]=useState(''),[branch,setBranch]=useState(''),[pullRequest,setPullRequest]=useState('');const [structures,setStructures]=useState<DocTemplate[]>([]);
 useEffect(()=>{Promise.all([api<ProjectSettings>('/project-settings/'+encodeURIComponent(task.project||'AI H Platform')),api<DocTemplate[]>('/document-templates')]).then(([config,templates])=>{setStructures(templates);setAiPrompt(config.ai.instructions);const chosen=templates.find(t=>t.id===config.documentation.defaultTemplate);if(chosen){setDocumentStructure(chosen.name);setCustomSections(chosen.sections.join('\n'))}}).catch(()=>{})},[task.project]);
 const work={summary,evidence,aiPrompt,documentStructure,customSections,...(useGit?{repository,branch,pullRequest}:{})};return <><div className="scrim"/><div className="submission"><header><div><span className="issue-key">{task.id}</span><h1>Submit completed work</h1><p>Add the proof that fits your task—Git information is only needed for code-based work.</p></div><button className="icon-btn" onClick={close}><X/></button></header>{busy?<div className="generating"><Sparkles size={38}/><h2>Generating documentation</h2>{['Saving employee submission…','Reading your chosen format…','Applying your AI instructions…','Analyzing evidence…','Generating documentation…'].map((x,i)=><p key={x} className={i<3?'done':''}><CheckCircle2 size={16}/>{x}</p>)}</div>:<div className={'submission-grid '+(!useGit?'no-git':'')}><div><section className="task-context"><span>ORIGINAL TASK</span><h3>{task.title}</h3><p>{task.description}</p></section><label className="work-summary">What did you do?<textarea value={summary} onChange={e=>setSummary(e.target.value)}/></label><section className="structure-choice"><div><h3>Documentation format</h3><p>Choose the format that best fits this work.</p></div><select value={documentStructure} onChange={e=>{setDocumentStructure(e.target.value);setCustomSections(structures.find(t=>t.name===e.target.value)?.sections.join('\n')||'')}}>{structures.length?structures.map(t=><option key={t.id}>{t.name}</option>):<option>Technical implementation guide</option>}<option>Custom structure</option></select>{documentStructure==='Custom structure'&&<textarea value={customSections} onChange={e=>setCustomSections(e.target.value)} placeholder="List the sections you want, for example: Context, Findings, Recommendation, Evidence, Next steps."/>}</section><label className="ai-instructions"><span><Sparkles size={15}/> Instructions for AI <em>Optional</em></span><textarea value={aiPrompt} onChange={e=>setAiPrompt(e.target.value)} placeholder="Example: Write this for a client, focus on business outcomes, and include recommendations."/><small>These instructions fine-tune the generated document.</small></label><section><h3>Evidence</h3><div className="evidence-grid">{['Screenshot','File','Code','Video','Audio'].map(x=><button key={x} onClick={()=>setEvidence(current=>current.some(item=>item.startsWith(x))?current.filter(item=>!item.startsWith(x)):[...current,x+' evidence'])}><Upload size={18}/>{evidence.some(item=>item.startsWith(x))?'Attached':x}</button>)}</div></section><label className="git-toggle"><input type="checkbox" checked={useGit} onChange={e=>setUseGit(e.target.checked)}/><span><b>This work includes GitHub / Git changes</b><small>Turn this on only for code-based work.</small></span></label></div>{useGit&&<aside className="git-card"><div><span className="git-logo">⌘</span><b>GitHub / Git</b><Badge kind="blue">Optional</Badge></div><label>Repository<input value={repository} onChange={e=>setRepository(e.target.value)} placeholder="organization/repository"/></label><label>Branch<input value={branch} onChange={e=>setBranch(e.target.value)} placeholder="feature/my-work"/></label><label>Pull request<input value={pullRequest} onChange={e=>setPullRequest(e.target.value)} placeholder="#123 Pull request title"/></label></aside>}</div>}<footer><button className="secondary" onClick={close}>Cancel</button><button className="create" disabled={!summary.trim()} onClick={()=>{setBusy(true);setTimeout(()=>generate(task,work),900)}}><Sparkles size={16}/> Submit &amp; generate documentation</button></footer></div></>}
function DocumentEditor({task,close,approve}:{task:Task,close:()=>void,approve:()=>void}){const [edit,setEdit]=useState(false),[notice,setNotice]=useState('');const text=`# ${task.title}\n\n## Overview\nThis document captures the implementation delivered for ${task.id}, including the technical approach, configuration, and validation.\n\n## Purpose\nThe change provides a reliable, secure path while keeping the integration maintainable for the engineering team.\n\n## Implementation\nThe feature uses a dedicated service boundary to validate requests, normalize provider responses, and persist the resulting state. Failure states are handled explicitly.\n\n## Architecture\nThe UI initiates the flow, the API validates the callback, and the identity service creates or links the user session. Audit events record authorization attempts.\n\n## Configuration\nSet provider credentials in the environment configuration. Redirect URLs must be registered for each environment.\n\n## Testing\nUnit tests cover callback handling and validation. Integration tests exercise successful sign-in, expired session, and denied-consent paths.\n\n## Security considerations\nState parameters are verified on callback. Refresh credentials are stored securely and rotated on use.`;return <div className="document-view"><header><div className="crumb"><span>Documentation</span><ChevronDown size={14}/><b>{task.id}</b></div><div className="top-actions"><button className="secondary" onClick={()=>setEdit(!edit)}>{edit?'Preview':'Edit'}</button><button className="secondary" onClick={()=>setNotice('AI improved the structure and added implementation details.')}><Sparkles size={15}/> Improve with AI</button><button className="secondary">Export</button><button className="create" onClick={approve}><CheckCircle2 size={16}/> Approve documentation</button><button className="icon-btn" onClick={close}><X/></button></div></header><div className="document-layout"><aside className="toc"><b>ON THIS PAGE</b>{['Overview','Purpose','Implementation','Architecture','Configuration','Testing','Security considerations'].map(x=><a href={'#'+x.replaceAll(' ','-')} key={x}>{x}</a>)}<hr/><small>Generated by AI H<br/>Based on submitted work</small></aside><article className="document"><span className="generated"><Sparkles size={14}/> AI-generated documentation</span>{edit?<textarea className="doc-edit" defaultValue={text}/>:text.split('\n\n').map((x,i)=>x.startsWith('# ')?<h1 key={i}>{x.slice(2)}</h1>:x.startsWith('## ')?<h2 id={x.slice(3).replaceAll(' ','-')} key={i}>{x.slice(3)}</h2>:<p key={i}>{x}</p>)}<div className="doc-footer">Last updated today at 10:24 AM · Version 1.0</div></article><aside className="ai-panel"><div><span className="ai-orb"><Sparkles/></span><h3>AI H Assistant</h3><p>Refine this documentation with AI.</p></div>{['Make this more technical','Add implementation details','Explain the API','Improve the structure','Generate examples','Make it shorter'].map(x=><button key={x} onClick={()=>setNotice('AI H updated the document: '+x)}>{x}<ArrowUpRight size={13}/></button>)}<div className="ask"><input placeholder="Ask AI…"/><Send size={15}/></div>{notice&&<p className="ai-response"><Bot size={15}/>{notice}</p>}</aside></div></div>}
type PlannerTask=Task&{assignedDate?:string,dueDate?:string,estimateHours?:number};
const teamMembers=[['Ahmed','AH'],['Sara','SA'],['Omar','OM'],['Lina','LI'],['Yousef','YO']] as const;

function IssueDrawerWithPlanning({task,tasks,close,submit,change,workMode,openDoc}:{task:Task,tasks:Task[],close:()=>void,submit:()=>void,change:(x:Partial<Task>)=>void,workMode?:boolean,openDoc?:()=>void}){
 const [members,setMembers]=useState(teamMembers);
 useEffect(()=>{api<ProjectSettings>('/project-settings/'+encodeURIComponent(task.project||'AI H Platform')).then(config=>setMembers(config.members.map(m=>[m.name,m.initials]))).catch(()=>{})},[task.project]);
 const planned=task as PlannerTask;
 const dependencies=task.dependencies||[];
 const save=(patch:Partial<PlannerTask>)=>change(patch as Partial<Task>);
 return <><div className="scrim" onClick={close}/><aside className={'drawer '+(workMode?'work-task-drawer':'')} aria-label={`Task ${task.id}`}>
  <div className="drawer-head"><span className="issue-key"><CircleDot size={16}/>{task.id}</span><div><button className="icon-btn" aria-label="More task actions"><MoreHorizontal size={18}/></button><button className="icon-btn" onClick={close} aria-label="Close task"><X size={19}/></button></div></div>
  <div className="drawer-title"><h1>{task.title}</h1><div><button className="status-button" onClick={()=>change({status:task.status==='Done'?'To Do':'Done'})}><CheckCircle2 size={15}/>{task.status}<ChevronDown size={13}/></button><button className="secondary">{task.priority}<ChevronDown size={13}/></button></div></div>
  <div className="drawer-body"><div className="issue-main"><h4>Description</h4><p>{task.description} The implementation should be production-ready, covered by tests, and follow existing platform conventions.</p><h4>Requirements</h4><ul><li>Implement the agreed technical solution.</li><li>Cover important error and edge cases.</li><li>Provide evidence and a clear work summary.</li></ul>
   <section className="task-planning"><div className="planning-heading"><Calendar size={16}/><div><h4>Schedule &amp; estimate</h4><small>Managers set dates and assignments. Employees maintain their own estimate.</small></div></div><div className="planning-fields"><label><span>Assigned date</span><input type="date" value={planned.assignedDate||''} onChange={e=>save({assignedDate:e.target.value})}/></label><label><span>Due date</span><input type="date" value={planned.dueDate||''} onChange={e=>save({dueDate:e.target.value})}/></label><label><span>Your estimate (hours)</span><input type="number" min="0" step="0.5" value={planned.estimateHours??''} onChange={e=>save({estimateHours:e.target.value===''?undefined:Number(e.target.value)})} placeholder="e.g. 6"/></label></div></section>
   <section className="dependency-summary"><div className="dependency-heading"><Layers size={16}/><div><h4>Dependencies</h4><small>{dependencies.length?'This task has linked work.':'This task has no dependencies.'}</small></div></div>{dependencies.length?<div className="dependency-list">{dependencies.map(dependency=>{const linked=tasks.find(item=>item.id===dependency.issueId);const label=dependency.type==='blockedBy'?'Blocked by':dependency.type==='blocks'?'Blocks':'Related to';return <div className={'dependency-item '+dependency.type} key={dependency.type+dependency.issueId}><span>{label}</span><b>{dependency.issueId} · {linked?.title||'Linked task'}</b><Badge kind={linked?.status==='Done'?'doc-state approved':'doc-state needs-review'}>{linked?.status||'Unknown status'}</Badge></div>})}</div>:<p className="dependency-clear"><CheckCircle2 size={15}/> No other task must be completed before this one.</p>}</section>
   {task.submission&&<section className="employee-work"><div className="work-heading"><span><Upload size={15}/></span><div><h4>Employee submitted work</h4><small>{task.submission.submittedAt?'Submitted '+new Date(task.submission.submittedAt).toLocaleString():'Submitted work'}</small></div></div><h5>What was completed</h5><p>{task.submission.summary}</p><h5>Evidence</h5><div className="submitted-evidence">{task.submission.evidence.length?task.submission.evidence.map(item=><span key={item}><Paperclip size={13}/>{item}</span>):<small>No evidence attached.</small>}</div></section>}
   <h4>Comments <button className="link-btn">Add comment</button></h4><div className="comment"><Avatar name="Sara" initials="SA"/><p><b>Sara Khalil</b><small>Yesterday</small>Looks good. Please include the edge cases around expired sessions.</p></div></div>
   <aside className="issue-details"><h4>Details</h4><label className="task-assignee"><span>Assignee</span><select value={task.assignee} onChange={e=>{const member=members.find(([name])=>name===e.target.value);save({assignee:e.target.value,initials:member?.[1]||task.initials})}}>{members.map(([name])=><option key={name}>{name}</option>)}</select></label>{[['Sprint','Sprint 12'],['Epic',task.epic],['Story points',String(task.points)],['Documentation',task.doc]].map(([x,y])=><div key={x}><span>{x}</span><b>{y}</b></div>)}<h4>Labels</h4><div className="labels">{task.labels.map(x=><Badge key={x}>{x}</Badge>)}</div></aside></div>
  <footer>{task.status!=='Done'&&<button className="create" onClick={submit}><Upload size={16}/> Submit work</button>}{task.doc!=='Not Started'&&openDoc&&<button className="secondary" onClick={openDoc}>View documentation</button>}<button className="secondary" onClick={close}>Close</button></footer>
 </aside></>;
}

function AssignTaskModal({close,add,config}:{close:()=>void,add:(t:any)=>void,config?:ProjectSettings}){
 const members=config?.members||teamMembers.map(([name,initials])=>({name,initials,fullName:name,role:'Contributor'}));
 const [title,setTitle]=useState(''),[assignee,setAssignee]=useState(members.find(m=>m.role==='Project lead')?.name||members[0]?.name||'Ahmed'),[assignedDate,setAssignedDate]=useState(new Date().toISOString().slice(0,10)),[dueDate,setDueDate]=useState(''),[priority,setPriority]=useState('Medium'),[description,setDescription]=useState(''),[issueType,setIssueType]=useState(config?.issueTypes.defaultType||'Task');
 const create=()=>{if(!title.trim())return;const member=members.find(m=>m.name===assignee);add({title:title.trim(),status:config?.workflows.defaultStatus||'To Do',priority,points:3,labels:['platform'],description,issueType,assignee,initials:member?.initials||'AH',assignedDate,dueDate:dueDate||undefined})};
 return <><div className="scrim" onClick={close}/><form className="modal task-create-modal" onSubmit={e=>{e.preventDefault();create()}}><div className="modal-head"><div><h2>Assign task</h2><p>{config?.details.name||'Create a task and assign it to a team member.'}</p></div><button type="button" className="icon-btn" onClick={close}><X/></button></div><label>Task name<input required autoFocus value={title} onChange={e=>setTitle(e.target.value)} placeholder="What needs to be done?"/></label><div className="form-row"><label>Assign to<select value={assignee} onChange={e=>setAssignee(e.target.value)}>{members.map(member=><option key={member.name} value={member.name}>{member.fullName}</option>)}</select></label><label>Issue type<select value={issueType} onChange={e=>setIssueType(e.target.value)}>{(config?.issueTypes.names||['Task','Story','Bug','Documentation']).map(name=><option key={name}>{name}</option>)}</select></label></div><div className="form-row"><label>Assigned date<input type="date" value={assignedDate} onChange={e=>setAssignedDate(e.target.value)}/></label><label>Due date<input type="date" min={assignedDate||undefined} value={dueDate} onChange={e=>setDueDate(e.target.value)}/></label></div><label>Priority<select value={priority} onChange={e=>setPriority(e.target.value)}>{['Medium','High','Highest','Low'].map(value=><option key={value}>{value}</option>)}</select></label><label>Description<textarea value={description} onChange={e=>setDescription(e.target.value)} placeholder="Add context, requirements, or acceptance criteria..."/></label><footer><button type="button" className="secondary" onClick={close}>Cancel</button><button className="create" disabled={!title.trim()}>Create &amp; assign</button></footer></form></>;
}

IssueDrawer = IssueDrawerWithPlanning;
createRoot(document.getElementById('root')!).render(<App/>);
